  "ascent.moment.their-relief-seen.steadyD": "Two hosts at once is how a line dies.",
  "ascent.moment.our-relief-near.title": "Our own relief is two hours out.",
  "ascent.moment.our-relief-near.commit": "Press now and fix them here",
  "ascent.moment.our-relief-near.commitD": "Hold them in place until it lands.",
  "ascent.moment.our-relief-near.steady": "Hold and wait for it",
  "ascent.moment.our-relief-near.steadyD": "Nothing is worth spending before it arrives.",
  "ascent.moment.they-offer-terms.title": "{subject} sends a rider under a white cloth.",
  "ascent.moment.they-offer-terms.commit": "Send him back with nothing",
  "ascent.moment.they-offer-terms.commitD": "Terms offered mid-fight are terms they need.",
  "ascent.moment.they-offer-terms.steady": "Hear him out",
  "ascent.moment.they-offer-terms.steadyD": "A pause is a pause for both of us.",
  "ascent.moment.captured-scout.title": "A scout of theirs has been taken.",
  "ascent.moment.captured-scout.commit": "Make him talk",
  "ascent.moment.captured-scout.commitD": "What he knows, we can use this hour.",
  "ascent.moment.captured-scout.steady": "Send him back with a message",
  "ascent.moment.captured-scout.steadyD": "Let him carry our numbers back. Doubled.",
  "ascent.moment.arms-favour-us.title": "Their arms cannot answer ours.",
  "ascent.moment.arms-favour-us.commit": "Press the advantage now",
  "ascent.moment.arms-favour-us.commitD": "It lasts as long as their line does.",
  "ascent.moment.arms-favour-us.steady": "Keep the shape and grind",
  "ascent.moment.arms-favour-us.steadyD": "The advantage does not spoil. Do not buy it twice.",
  "ascent.moment.arms-favour-them.title": "Their arms are wrong for ours.",
  "ascent.moment.arms-favour-them.commit": "Close before it tells",
  "ascent.moment.arms-favour-them.commitD": "At arm's length the matchup stops mattering.",
  "ascent.moment.arms-favour-them.steady": "Give ground and refuse",
  "ascent.moment.arms-favour-them.steadyD": "Fight them on a day we choose.",
