  "ascent.moment.sworn-oath.commit": "Swear before them",
  "ascent.moment.sworn-oath.commitD": "No step back. Say it out loud and mean it.",
  "ascent.moment.sworn-oath.steady": "Say nothing and fight",
  "ascent.moment.sworn-oath.steadyD": "Words are cheap at this hour. Blades are not.",
  "ascent.moment.village-behind.title": "{subject} is close behind our line.",
  "ascent.moment.village-behind.commit": "Fight in front of the hedge",
